Method.Source:
/// <summary>
/// Find method by external tracking Id
/// </summary>
/// <param name = "_externalTrackingId">Trial balance snapshot external tracking Id</param>
/// <param name = "_forUpdate">Select record for update</param>
/// <returns><c>LedgerTrialBalanceSnapshotHeader</c></returns>
static LedgerTrialBalanceSnapshotHeader METFindTrackingId(Guid     _externalTrackingId,
                                                          boolean  _forUpdate = false)
{
    LedgerTrialBalanceSnapshotHeader header;

    if (_externalTrackingId)
    {
        if (_forUpdate)
        {
            header.selectForUpdate(_forUpdate);
        }

        select firstonly header
                   where header.ExternalTrackingId == _externalTrackingId;
    }

    return header;
}
